#include "dk1/scene_memory.h"
#include <string.h>
static bool palette_apply(const Dk1RomImage*r,const Dk1ScenePaletteUpload*u,Dk1CgramImage*c){size_t bytes=(size_t)u->x_count*8u,colors=bytes/2u,i;if(u->mode==DK1_PALETTE_UPLOAD_NORMAL)return dk1_cgram_upload_b9(r,u->source_b9,u->cgram_start,u->x_count,c);if((size_t)u->cgram_start+colors>256u)return false;for(i=0;i<colors;i++){uint8_t lo=0,hi=0;if(!dk1_rom_read_u8(r,0xB90000u|((u->source_b9+(uint16_t)(i*2u))&0xFFFFu),&lo)||!dk1_rom_read_u8(r,0xB90000u|((u->source_b9+(uint16_t)(i*2u+1u))&0xFFFFu),&hi))return false;c->colors[u->cgram_start+i]=(uint16_t)((uint8_t)~lo)|((uint16_t)(uint8_t)~hi<<8u);}return true;}
bool dk1_scene_memory_load(const Dk1RomImage*r,uint16_t id,bool special,bool state6,Dk1SceneMemory*s){size_t i;if(!r||!s)return false;memset(s,0,sizeof(*s));if(!dk1_scene_recipe_for_level(r,id,&s->recipe)||!dk1_scene_package_plan(id,s->recipe.primary_vram_package,special,state6,&s->packages)||!dk1_ppu_preset_read(r,s->recipe.ppu_preset,&s->ppu)||!dk1_level_terrain_config_read(r,s->recipe.terrain_profile,&s->terrain)||!dk1_level_camera_bounds_read(r,id,&s->camera))return false;dk1_vram_image_init(&s->vram);for(i=0;i<s->packages.count;i++)if(!dk1_vram_apply_package(r,s->packages.ids[i],&s->vram,NULL))return false;dk1_cgram_init(&s->cgram);for(i=0;i<s->recipe.palette_upload_count;i++)if(!palette_apply(r,&s->recipe.palette_uploads[i],&s->cgram))return false;if(s->recipe.patch_special_palette){s->cgram.colors[0]=0x4210u&0x7FFFu;s->cgram.colors[0x11]=0x7FFFu;}return true;}
